export class Solution {
    divHost: HTMLElement;
    canvas: HTMLCanvasElement;
    ctx: GPUCanvasContext;
    device: GPUDevice;
    format: GPUTextureFormat;
    size: any;
    pipelineObj: any;
    mouse = new Float32Array([
        0,0
     ]);
    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        //     console.log(id, 'webGPU', navigator.gpu);
        this.canvas = document.createElement('canvas');
        this.divHost.appendChild(this.canvas);

        this.canvas.addEventListener('mousemove', (e: MouseEvent) => {
            // console.log('move dragging')
            const xOff = this.mouse[0] - e.offsetX;
            const yOff = this.mouse[1] - e.offsetY;

            this.mouse[0] = e.offsetX;
            this.mouse[1] = e.offsetY;

            console.log('mousemove', e);
        }, false);

        this.initWebGPU();
    }
    async initWebGPU() {
        if (!navigator.gpu) { throw new Error('Not Support WebGPU'); }

        const adapter = await navigator.gpu.requestAdapter({
            powerPreference: 'high-performance'
            // powerPreference: 'low-power'
        })

        if (!adapter) { throw new Error('No Adapter Found'); }

        const device = await adapter.requestDevice()
        this.ctx = this.canvas.getContext('webgpu') as GPUCanvasContext
        // @ts-ignore
        const format = navigator.gpu.getPreferredCanvasFormat ? navigator.gpu.getPreferredCanvasFormat() : this.ctx.getPreferredFormat(adapter)
        const devicePixelRatio = window.devicePixelRatio || 1
        this.canvas.width = this.divHost.clientWidth;
        this.canvas.height = this.divHost.clientHeight;
        this.ctx.configure({
            // json specific format when key and value are the same
            device, format,
            // prevent chrome warning
            alphaMode: 'opaque'
        })

        this.size = { width: this.canvas.width, height: this.canvas.height }
        this.device = device;
        this.format = format;

        this.initPipeline(this.device, this.format);
    }
    async initPipeline(device: GPUDevice, format: GPUTextureFormat, primitiveType = 'triangle-list') { // triangle-list , triangle-strip
        let indexFormat = undefined;
        if (primitiveType === 'line-strip') {
            indexFormat = 'uint32'
        }

        const shader = Shaders();
        const pipeline = device.createRenderPipeline({
            layout: 'auto',
            vertex: {
                module: device.createShaderModule({
                    code: shader.vertex
                }),
                entryPoint: "main"
            },
            fragment: {
                module: device.createShaderModule({
                    code: shader.fragment
                }),
                entryPoint: "main",
                targets: [{
                    format: format as GPUTextureFormat
                }]
            },
            primitive: {
                topology: primitiveType as GPUPrimitiveTopology,
                stripIndexFormat: indexFormat as GPUIndexFormat
            }
        });

        const commandEncoder = device.createCommandEncoder();
        const textureView = this.ctx.getCurrentTexture().createView();

        const renderPass = commandEncoder.beginRenderPass({
            //@ts-ignore
            colorAttachments: [{
                view: textureView as GPUTextureView,
                clearValue: [0.0, 0.0, 0.0, 1], //background color
                loadOp: 'clear',
                storeOp: 'store'
            }]
        });
        renderPass.setPipeline(pipeline);
        renderPass.draw(9, 1, 0, 0);
        // renderPass.draw(6);
        renderPass.end();

        device.queue.submit([commandEncoder.finish()]);

    }
    public destroy() {
        this.device.destroy();
        while (this.divHost.lastElementChild) {
            this.divHost.removeChild(this.divHost.lastElementChild);
        }
    }
}

export const CreateGPUBuffer = (device: GPUDevice, data: Float32Array,
    usageFlag: GPUBufferUsageFlags = GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST) => {
    const buffer = device.createBuffer({
        size: data.byteLength,
        usage: usageFlag,
        mappedAtCreation: true
    });
    new Float32Array(buffer.getMappedRange()).set(data);
    buffer.unmap();
    return buffer;
}


